changeSet.sql:
ALTER TABLE air_temperature_extra_fee
    ADD CONSTRAINT chk_air_temperature_extra_fee_positive
        CHECK (fee > 0);
ALTER TABLE air_temperature_extra_fee
    ADD CONSTRAINT chk_air_temperature_extra_fee_range_bounded
        CHECK (min_air_temperature IS NOT NULL OR max_air_temperature IS NOT NULL);
ALTER TABLE air_temperature_extra_fee
    ADD CONSTRAINT chk_air_temperature_extra_fee_min_less_than_max
        CHECK (min_air_temperature < max_air_temperature);
